/// Raven `BG_InGrappleMove`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:672-690`
pub fn BG_InGrappleMove(anim: c_int) -> c_int {
    use animNumber_t::*;
    if [BOTH_KYLE_GRAB as c_int, BOTH_KYLE_MISS as c_int].contains(&anim) {
        return 1; //grabbing at someone
    }
    if [BOTH_KYLE_PA_1 as c_int, BOTH_KYLE_PA_2 as c_int].contains(&anim) {
        return 2; //beating the shit out of someone
    }
    if [
        BOTH_PLAYER_PA_1 as c_int,
        BOTH_PLAYER_PA_2 as c_int,
        BOTH_PLAYER_PA_FLY as c_int,
    ]
    .contains(&anim)
    {
        return 3; //getting the shit beaten out of you
    }
    0
}

/// Raven `BG_BrokenParryForAttack`.
///
/// Our attack was knocked away by a knockaway parry.
/// FIXME (Raven): need actual anims for this; need to know which side of the
/// saber was hit — for now presumes the saber gets knocked away from center.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:692-725`
impl PmoveContext<'_> {
    pub fn BG_BrokenParryForAttack(&mut self, r#move: c_int) -> c_int {
        match self.bg.saberMoveData[r#move as usize].startQuad {
            Q_B => LS_V1_B_,
            Q_BR => LS_V1_BR,
            Q_R => LS_V1__R,
            Q_TR => LS_V1_TR,
            Q_T => LS_V1_T_,
            Q_TL => LS_V1_TL,
            Q_L => LS_V1__L,
            Q_BL => LS_V1_BL,
            _ => LS_NONE,
        }
    }
}

/// Raven `BG_BrokenParryForAttack` — free-function form for game-tier callers.
///
/// Our attack was knocked away by a knockaway parry.
/// FIXME (Raven): need actual anims for this; need to know which side of the
/// saber was hit — for now presumes the saber gets knocked away from center.
///
/// Game-tier callers without a PmoveContext receiver call this form, passing
/// a reference to the BgState that owns the saberMoveData table.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:692-725`
pub fn BG_BrokenParryForAttack(bg_state: &crate::bg_channel::BgState, r#move: c_int) -> c_int {
    match bg_state.saberMoveData[r#move as usize].startQuad {
        Q_B => LS_V1_B_,
        Q_BR => LS_V1_BR,
        Q_R => LS_V1__R,
        Q_TR => LS_V1_TR,
        Q_T => LS_V1_T_,
        Q_TL => LS_V1_TL,
        Q_L => LS_V1__L,
        Q_BL => LS_V1_BL,
        _ => LS_NONE,
    }
}

/// Raven `BG_BrokenParryForParry`.
///
/// FIXME (Raven): need actual anims for this; need to know which side of the
/// saber was hit — for now presumes the saber gets knocked away from center.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:727-761`
pub fn BG_BrokenParryForParry(bg_state: &mut crate::bg_channel::BgState, r#move: c_int) -> c_int {
    match r#move {
        LS_PARRY_UP => {
            // Since we don't know what dir the hit came from, randomly pick knock down or knock back.
            if bg_state.rng.Q_irand(0, 1) != 0 {
                LS_H1_B_
            } else {
                LS_H1_T_
            }
        }
        LS_PARRY_UR => LS_H1_TR,
        LS_PARRY_UL => LS_H1_TL,
        LS_PARRY_LR => LS_H1_BR,
        LS_PARRY_LL => LS_H1_BL,
        LS_READY => LS_H1_B_, //???
        _ => LS_NONE,
    }
}

/// Raven `BG_KnockawayForParry`.
///
/// FIXME (Raven): need actual anims for this; need to know which side of the
/// saber was hit — for now presumes the saber gets knocked away from center.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:763-787`
pub fn BG_KnockawayForParry(r#move: c_int) -> c_int {
    if r#move == BLOCKED_TOP as c_int {
        LS_K1_T_ //push up
    } else if r#move == BLOCKED_UPPER_LEFT as c_int {
        LS_K1_TL //push up and to left
    } else if r#move == BLOCKED_LOWER_RIGHT as c_int {
        LS_K1_BR //push down and to left
    } else if r#move == BLOCKED_LOWER_LEFT as c_int {
        LS_K1_BL //push down and to right
    } else {
        /* BLOCKED_UPPER_RIGHT and default */
        LS_K1_TR //push up, slightly to right
    }
}

