/// Raven `BG_HasAnimation`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2933-2955`
impl PmoveContext<'_> {
    pub fn BG_HasAnimation(&mut self, animIndex: c_int, animation: c_int) -> qboolean {
        if animation < 0 || animation >= MAX_ANIMATIONS as c_int {
            return 0;
        }

        if animIndex < 0 || animIndex > self.bg.bgNumAllAnims {
            return 0;
        }

        let animations = self.bg.bgAllAnims[animIndex as usize].anims;

        if unsafe { (*animations.offset(animation as isize)).numFrames } == 0 {
            return 0;
        }

        1
    }
}

/// Raven `BG_HasAnimation` — free-function form for game-tier callers.
///
/// Game-tier callers without a PmoveContext receiver call this form, passing
/// a reference to the BgState that owns the bgAllAnims table.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2933-2955`
pub fn BG_HasAnimation(
    bg_state: &crate::bg_channel::BgState,
    animIndex: c_int,
    animation: c_int,
) -> qboolean {
    if animation < 0 || animation >= MAX_ANIMATIONS as c_int {
        return 0;
    }

    if animIndex < 0 || animIndex > bg_state.bgNumAllAnims {
        return 0;
    }

    let animations = bg_state.bgAllAnims[animIndex as usize].anims;

    if unsafe { (*animations.offset(animation as isize)).numFrames } == 0 {
        return 0;
    }

    1
}

/// Raven `BG_PickAnim`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2957-2975`
pub fn BG_PickAnim(
    bg_state: &mut crate::bg_channel::BgState,
    animIndex: c_int,
    minAnim: c_int,
    maxAnim: c_int,
) -> c_int {
    let mut anim;
    let mut count = 0;
    loop {
        anim = bg_state.rng.Q_irand(minAnim, maxAnim);
        count += 1;
        if BG_HasAnimation(bg_state, animIndex, anim) != 0 || count >= 1000 {
            break;
        }
    }

    if count == 1000 {
        //guess we just don't have a death anim then.
        return -1;
    }

    anim
}

/// Raven `BG_SetAnim`.
///
/// Raven: I want to be able to use this on a playerstate even when we are not
/// the focus of a pmove too so I have ported it to true BGishness. Please do
/// not reference pm in this function or any functions that it calls, or I
/// will cry. -rww
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:2981-3035`
impl PmoveContext<'_> {
    pub fn BG_SetAnim(
        &mut self,
        ps: *mut playerState_t,
        mut animations: *mut animation_t,
        setAnimParts: c_int,
        anim: c_int,
        setAnimFlags: c_int,
        blendTime: c_int,
    ) {
        if animations.is_null() {
            animations = self.bg.bgAllAnims[0].anims;
        }

        unsafe {
            if (*animations.offset(anim as isize)).firstFrame == 0
                && (*animations.offset(anim as isize)).numFrames == 0
            {
                let mut fallback_anim = anim;
                if anim == BOTH_RUNBACK1 as c_int
                    || anim == BOTH_WALKBACK1 as c_int
                    || anim == BOTH_RUN1 as c_int
                {
                    fallback_anim = BOTH_WALK2 as c_int;
                }

                if (*animations.offset(fallback_anim as isize)).firstFrame == 0
                    && (*animations.offset(fallback_anim as isize)).numFrames == 0
                {
                    return;
                }
                animations = animations.offset((fallback_anim - anim) as isize);
            }

            if setAnimFlags & SETANIM_FLAG_OVERRIDE != 0 {
                if setAnimParts & SETANIM_TORSO != 0 {
                    if (setAnimFlags & SETANIM_FLAG_RESTART) != 0 || (*ps).torsoAnim != anim {
                        BG_SetTorsoAnimTimer(ps, 0);
                    }
                }
                if setAnimParts & SETANIM_LEGS != 0 {
                    if (setAnimFlags & SETANIM_FLAG_RESTART) != 0 || (*ps).legsAnim != anim {
                        BG_SetLegsAnimTimer(ps, 0);
                    }
                }
            }

            self.BG_SetAnimFinal(ps, animations, setAnimParts, anim, setAnimFlags, blendTime);
        }
    }
}

/// Raven `PM_SetAnim`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:3037-3040`
impl PmoveContext<'_> {
    pub fn PM_SetAnim(&mut self, setAnimParts: c_int, anim: c_int, setAnimFlags: c_int, blendTime: c_int) {
        let (ps, animations) = unsafe { ((*self.pm).ps, (*self.pm).animations) };
        self.BG_SetAnim(ps, animations, setAnimParts, anim, setAnimFlags, blendTime);
    }
}
